class TicTacToe {
    private final int n;
    private final int[] rows;
    private final int[] cols;
    private int diag;      // top-left to bottom-right
    private int anti;      // top-right to bottom-left

    public TicTacToe(int n) {
        this.n = n;
        this.rows = new int[n];
        this.cols = new int[n];
    }

    /** O(1) time, O(n) space. No board anywhere. */
    public int move(int row, int col, int player) {
        int delta = (player == 1) ? 1 : -1;

        rows[row] += delta;
        cols[col] += delta;
        if (row == col)         diag += delta;
        if (row + col == n - 1) anti += delta;

        boolean won = Math.abs(rows[row]) == n
                   || Math.abs(cols[col]) == n
                   || Math.abs(diag) == n
                   || Math.abs(anti) == n;

        return won ? player : 0;
    }
}

class TicTacToe:
    def __init__(self, n: int):
        self.n = n
        self.rows = [0] * n
        self.cols = [0] * n
        self.diag = self.anti = 0

    def move(self, row: int, col: int, player: int) -> int:
        delta = 1 if player == 1 else -1

        self.rows[row] += delta
        self.cols[col] += delta
        if row == col:
            self.diag += delta
        if row + col == self.n - 1:
            self.anti += delta

        if self.n in (abs(self.rows[row]), abs(self.cols[col]),
                      abs(self.diag), abs(self.anti)):
            return player
        return 0
